package copyfile

import (
	"io/fs"
	"math"
	"strings"

	"github.com/deploymenttheory/go-apfs-v3/filesystem"
	"github.com/deploymenttheory/go-apfs-v3/internal/metadata"
)

// ValidateMetadata admits the final copy state, never arbitrary command fields
// or filesystem-owned attributes. Ctime is generated by the mutation engine.
func ValidateMetadata(c filesystem.Change) error {
	if c.Operation != "copy-metadata" || c.Path == "" || c.Metadata == nil || c.Name != "" || c.Destination != "" || c.Parents || c.Recursive || c.Force || c.NoClobber || c.Data != nil || c.ResourceFork || c.Symbolic || c.Mode != "" || c.Flags != "" || c.Attribute != "" || c.AttributeMode != "" || c.DeleteAttribute || c.NoCreate || c.Reference != "" || c.Access || c.Modify {
		return fs.ErrInvalid
	}
	m := c.Metadata
	for _, field := range []filesystem.Observation[uint32]{m.Mode, m.UID, m.GID, m.BSDFlags} {
		if field.State != filesystem.Present {
			return fs.ErrInvalid
		}
	}
	if m.UID.Value == math.MaxUint32 || m.GID.Value == math.MaxUint32 || m.Mode.Value&^uint32(0177777) != 0 || m.Mode.Value&06000 != 0 || m.BSDFlags.Value&^metadata.UserFlags != 0 || m.ChangeTime.State != filesystem.Uncaptured {
		return filesystem.ErrUnsupported
	}
	if m.BirthTime.State != filesystem.Present || m.ModifyTime.State != filesystem.Present || m.AccessTime.State != filesystem.Present {
		return fs.ErrInvalid
	}
	if len(c.Attributes)+len(c.RemoveAttributes) > 4096 {
		return filesystem.ErrLimit
	}
	seen := map[string]bool{}
	for _, name := range c.RemoveAttributes {
		if seen[name] {
			return fs.ErrInvalid
		}
		seen[name] = true
		if name != filesystem.Decmpfs {
			if err := metadata.AttributeName(name); err != nil {
				return err
			}
		}
	}
	for name, value := range c.Attributes {
		if seen[name] || value == nil || value.Size() < 0 {
			return fs.ErrInvalid
		}
		if name == filesystem.Decmpfs {
			valid, err := CopyableCompression(value)
			if err != nil {
				return err
			}
			if !valid {
				return filesystem.ErrUnsupported
			}
		} else if err := metadata.AttributeName(name); err != nil {
			return err
		}
		if name != filesystem.ResourceFork && value.Size() > math.MaxInt32 {
			return filesystem.ErrLimit
		}
	}
	if c.Path != "/" && strings.HasSuffix(c.Path, "/") {
		return fs.ErrInvalid
	}
	return nil
}
